+const { useState } = React;
+
+function RadioOption({ name, value, label, checked, onChange }) {
+  return (
+    <label className={`option ${checked ? "selected" : ""}`}>
+      <input
+        type="radio"
+        name={name}
+        value={value}
+        checked={checked}
+        onChange={() => onChange(value)}
+      />
+      <span className="radio-dot" aria-hidden="true"></span>
+      <span className="option-label">{label}</span>
+    </label>
+  );
+}
+
+function NotificationForm() {
+  const [preference, setPreference] = useState("");
+  const [submitted, setSubmitted] = useState(null);
+
+  const options = [
+    { value: "email", label: "Email" },
+    { value: "sms", label: "SMS" },
+    { value: "push", label: "Push Notifications" },
+  ];
+
+  const handleSubmit = (e) => {
+    e.preventDefault();
+    if (!preference) return;
+    const chosen = options.find((o) => o.value === preference);
+    setSubmitted(chosen.label);
+  };
+
+  return (
+    <div className="card">
+      <h1>Notification Preferences</h1>
+      <p className="subtitle">Choose how you'd like us to reach you.</p>
+      <form onSubmit={handleSubmit}>
+        <div className="form-field">
+          <fieldset className="options">
+            <legend>How do you prefer to receive notifications?</legend>
+            {options.map((opt) => (
+              <RadioOption
+                key={opt.value}
+                name="notifications"
+                value={opt.value}
+                label={opt.label}
+                checked={preference === opt.value}
+                onChange={(v) => {
+                  setPreference(v);
+                  setSubmitted(null);
+                }}
+              />
+            ))}
+          </fieldset>
+        </div>
+        <button type="submit" className="submit-btn" disabled={!preference}>
+          Submit
+        </button>
+        {submitted && (
+          <div className="confirmation">
+            Preference saved: {submitted}
+          </div>
+        )}
+      </form>
+    </div>
+  );
+}
+
+ReactDOM.createRoot(document.getElementById("root")).render(<NotificationForm />);
